CREATE INDEX idx_reports_run_history ON integrity_reports(organization_id, run_id, analysis_revision, created_at, id);
CREATE UNIQUE INDEX idx_reports_job ON integrity_reports(organization_id, job_id) WHERE job_id IS NOT NULL;
CREATE FUNCTION integrity_guard_report_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status = 'ready' THEN RAISE EXCEPTION 'immutable report'; END IF; IF OLD.source_json IS NOT NULL AND (NEW.source_json IS DISTINCT FROM OLD.source_json OR NEW.source_hash IS DISTINCT FROM OLD.source_hash OR NEW.frozen_at IS DISTINCT FROM OLD.frozen_at OR NEW.run_id != OLD.run_id OR NEW.organization_id != OLD.organization_id OR NEW.analysis_revision != OLD.analysis_revision OR NEW.schema_version != OLD.schema_version OR NEW.revision != OLD.revision OR NEW.format != OLD.format OR NEW.created_at != OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.job_id IS DISTINCT FROM OLD.job_id) THEN RAISE EXCEPTION 'immutable report source'; END IF; RETURN NEW; END $$;
CREATE TRIGGER integrity_report_immutable BEFORE UPDATE ON integrity_reports FOR EACH ROW EXECUTE FUNCTION integrity_guard_report_immutable();
